/** Weights for the 8 serial digits of a UPU S10 number (docs/carriers.md). */
const S10_WEIGHTS = [8, 6, 4, 2, 3, 5, 9, 7];

/** `RR123456785AT`: 2 letters, 8 digits, 1 check digit, `AT`. */
const ATP_S10_FORMAT = /^[A-Z]{2}(\d{8})(\d)AT$/;

/** Check digit for the 8 serial digits of an S10 number. */
export function s10CheckDigit(serial: string): number {
  let sum = 0;
  for (let i = 0; i < S10_WEIGHTS.length; i++) sum += Number(serial[i]) * S10_WEIGHTS[i];
  const result = 11 - (sum % 11);
  if (result === 10) return 0;
  if (result === 11) return 5;
  return result;
}

export type AtpTrackingCheck = { ok: true } | { ok: false; reason: 'format' | 'check_digit'; expected?: number };

/** Validates an (already trimmed and upper-cased) Austrian Post tracking number. */
export function checkAtpTrackingNumber(trackingNumber: string): AtpTrackingCheck {
  const match = ATP_S10_FORMAT.exec(trackingNumber);
  if (!match) return { ok: false, reason: 'format' };
  const expected = s10CheckDigit(match[1]);
  if (Number(match[2]) !== expected) return { ok: false, reason: 'check_digit', expected };
  return { ok: true };
}
